/* ══⚠⚠ 北方泊地槍店的射擊挑戰（ver -655，Ray 交稿）══════════════════════
   **這一段只寫一次**（鐵律 7）：初次進店的 `lines` 與店裡「射擊挑戰」鈕的
   `challengeLines` 用的是同一份 —— 兩邊各抄一份的話，改台詞一定只改到一邊。
   ⚠ 分歧：接受→`np_go`／拒絕→`np_no`；**挑戰失敗與拒絕共用同一句**
     （Ray 的稿兩處都是「可惜！下次再挑戰吧！」），所以 `onLose` 指的是同一個 label。
   ⚠ `{ end:true }` ＝拒絕／失敗那一條到此為止：它後面躺著挑戰成功那十幾拍，
     沒有它就會掉進去（見 modules/story.js 的說明）。
   ⚠ 挑戰費 **200G 扣在選項上**（`cost`）：錢不夠時那個選項是暗的、按不動。
   ⚠ 「25 秒」是 `config.battles.np_range.timeAttack.parSec`（改那個數字要改這一句，
     兩邊註解互指）。
   ⚠ 強化的旗標記在**「嗯……完成了。」**那一拍（`flags` 是演到就記）——
     不記在戰勝那一拍：他還沒動手。 */
const NP_RANGE_SEQ = [
  gunN(null,'喔！想打靶嗎？咱這一區的記錄可是25秒，破得了的話……'),
  /* 這兩拍是**還沒領過獎品**時才講（ver -656，Ray：「成功以後挑戰不用錢
     但也不會有強化事件」）—— 已經調校過了就不再提獎品，也不再收錢。 */
  Object.assign(gunN(null,'現在我也拿不出像樣的東西，就免費幫你調校一下那兩把槍吧！'),
                { skipIf:'np_gun_tuned' }),
  Object.assign(gunN(null,'挑戰費200G喔。'), { skipIf:'np_gun_tuned' }),
  /* ⚠ `costUntil` ＝那支旗立起來之後就**免費**（同上）。
     ⚠ 挑戰**失敗**不會立旗，所以要再挑戰就得再付一次 —— 那正是 Ray 要的。 */
  { choice:[ { text:'接受', goto:'np_go', cost:200, costUntil:'np_gun_tuned' },
             { text:'拒絕', goto:'np_no' } ] },
  /* —— 拒絕／挑戰失敗（同一句，Ray 的稿）—— */
  Object.assign(gunN(null,'可惜！下次再挑戰吧！'), { label:'np_no' }),
  { end:true },
  /* —— 接受 —— */
  Object.assign(gunN(null,'好！放開手腳上吧！'), { label:'np_go' }),
  { battle:'np_range', onLose:'np_no' },
  /* —— 挑戰成功 —— */
  gunN(null,'真是驚人啊！'),
  /* 已經調校過了 → 到此為止（ver -656）：獎品只有一次。 */
  { end:true, onlyIf:'np_gun_tuned' },
  gunN(null,'依照約定，我來幫你做些強化。'),
  /* 三個音效各一拍（Ray：「依序 se_ui_click, se_ginclick, se_ui_sortie」）。
     ⚠ 沒有台詞就一定要給 `auto`（沒有框就沒有 ▼，§6.5）；立繪維持在台上。
     ⚠⚠ `noHold:true`（ver -703，Ray：「要自動三連播，不要點擊才播下一個」）——
       台上有立繪的無台詞拍預設要點擊才推進（§6.5 的 -628），但**這三拍是一串
       音效**，中間要人點三下就斷了節奏。 */
  { speaker:'GUNSMITH_NP', text:'', auto:800, noHold:true, se:'se_ui_click',
    portrait:{ char:'GUNSMITH_NP', show:true } },
  { speaker:'GUNSMITH_NP', text:'', auto:800, noHold:true, se:'se_ginclick',
    portrait:{ char:'GUNSMITH_NP', show:true } },
  { speaker:'GUNSMITH_NP', text:'', auto:800, noHold:true, se:'se_ui_sortie',
    portrait:{ char:'GUNSMITH_NP', show:true } },
  /* ⚠ `gunStar:'albali'` ＝點亮**吞噬者**一次（ver -707；-700 的 `gunTune:1` 改寫）。
     九階改成非線性之後，「特殊事件給的強化」要指名是**哪一顆星** ——
     槍匠說的是「膛壓增強了」＝普攻攻擊力 +5%，正是吞噬者，也與 ver -655
     Ray 原本的「主槍普攻攻擊力強化 5%」完全對得上。
     旗標照舊記著：它管的是「重挑戰不必再付 200G」。 */
  Object.assign(gunN(null,'嗯……完成了。'), { flags:['np_gun_tuned'], gunStar:'albali' }),
  gunN(null,'膛壓增強了，後座力也會強一點，不過你應該沒問題。'),
  gunN(null,'不過，這兩把槍的名字是南方的古文吧。有什麼典故嗎？'),
  { speaker:'PLAYER', blank:true },
  gunN(null,'喔？哈哈哈！真是浪漫啊！'),
  gunN(null,'那就，祝你們一路順風！'),
];
/* 北方泊地雜貨店店主（ver -655，Ray 交稿）。⚠ 進場對白與「交談」鈕共用這一份。 */
/* ver -858（Ray 交稿）：城鎮被毀但積極樂觀、苦中作樂＋空賊情報兩則。
   ⚠ 第一句是我補的開場（Ray 給的是方向「積極樂觀，苦中作樂」）。 */
const NP_GROCER_LINES = [
  groN(null,'喲，還活著就是賺到啦！要買什麼儘管說。'),
  groN(null,'北部空域似乎有空賊出沒，懸賞金不少。'),
  groN(null,'打空賊除了領賞金，還可以搜刮他們的財寶，是趟好買賣呢。'),
  groN(null,'苦著臉也沒用，日子還是得過。物資都被徵調了，貨品有限，抱歉啊。'),
];

/* ══════════════════════════════════════════════════════════════════════
   女角外出（ver -575，Ray 交稿）
   ──────────────────────────────────────────────────────────────────────
   「現在進城旅店中，女主角們在早上 8:00 到下午 6 點可能會出門，出門時不顯示頭像，
     一天最多出門兩次。出現區域是所有的連接用場景（非末端），以及各角色不同。」

   ⚠⚠ 這一組**取代** ver -461 的 `rennaOut`（鐵律 8：一個動作一支實作）——
     那是只給蕾娜寫的一份，四個人各寫一份必然走鐘。舊欄位已刪。
   ⚠ **「連接用場景」是算出來的，不是列出來的**（鐵律 7）：節點的 `exits` 裡有
     `back` 以外的方向＝它通往別的地方＝連接用（帝都的廣場／中心區／舊街區／上街區、
     北方泊地的中央大道／西側／北側／東側）。大城地圖已經規則化，所以列表一寫死，
     日後加一座城就漏一次。判定只有 `modules/town.js` 的 `connectorIds()` 一支。
   ⚠ **餐飲街也是每個人的區域**：她有 `dine` 就上得了那一格（見下方 DINE）——
     所以 `nodes` 只寫「連接場景與餐飲街以外」的那幾格。
   ⚠ 旅店本身不算（她就住在那裡，「出門」的意思是不在旅店）。

   ── 排程 ─────────────────────────────────────────────────────────
   `hours` 這一段切成 `perDay` 個等寬的窗，每個窗各擲一次 `chance`：
   中了就在那個窗內隨機挑開始時刻與停留長度。**這樣「一天最多兩次」是結構保證的**，
   不是靠事後數次數 —— 而且兩次不會重疊。
   ⚠ 行程是**這一座城的這一天**的狀態，存在記憶體裡（`modules/town.js` 的 `outPlan`），
     不進存檔：睡覺一定跨到隔天 07:00，醒來本來就要重排（同 `escortNou` 那一組）。
   ⚠ `from`＝這一章之後她才在隊上（與 `flight/talks.js` 的 `PARTY` 同義，兩邊註解互指）。
     安雅與索菈娜**暫填 5**（Ray 還沒定她們哪一章入隊，同 §6.10 那條）——
     定案了就改這兩個數字，其餘什麼都不必動。
   ⚠ `line` 是**佔位稿**（Ray 給了規則、沒給句子）：碰到她時她說的那一句。要換直接改。
   ══════════════════════════════════════════════════════════════════════ */
/* ══════════════════════════════════════════════════════════════════════════
 *  王座徘徊者・那一夜的追逐（ver -1389，Ray 交稿）
 * ──────────────────────────────────────────────────────────────────────────
 *  `modules/town.js` 的 `dragonActDue` 只決定「第幾場」，台詞在這裡（鐵律 1）。
 *  ⚠ 每一筆就是一個 act：`flag` 演完才記、`lines` 裡的 `{battle:…}` 是那一場。
 *  ⚠ 稿上幾處說話者與立繪對不上，**照立繪判**（同 -1346 的作法）：
 *    「諾：『諾薇兒，安靜下！』」配 `Sorana_*` ⇒ 索菈娜；
 *    「安：『快下降！…』」配 `Nouvelle_*` ⇒ 諾薇兒。
 *  ⚠ 稿上還沒有圖的表情用最近的既有差分頂著（Ray：「立繪先沿用」）。
 * ════════════════════════════════════════════════════════════════════════ */
export const DRAGON_LINES = {
  chase: [
    /* ① 進入主廳 —— 那一夜的第一場。 */
    /* ══⚠⚠⚠ **這一拍以前會換曲，ver -1444 拿掉了**（Ray 第三次回報：「追擊音樂從
       槍棺推上才開始播，要講幾次」）══
       ⚠⚠⚠ **真因是「同一首曲子有兩個播放點，而早的那個先贏」**（鐵律 7）：
         · -1398 在**這一拍**寫了 `bgm:'gothic'` —— 於是音樂在索菈娜這句台詞就起來了，
           距離槍棺上推還有四拍。
         · -1433 依 Ray 的指示加了戰鬥卡的 `bgmOnRise:true`（門一推就進）——
           但那時**沒有把上面那一行拿掉**。門推上去時 `gothic` 早就在播，
           `playBgm` 判成同曲直接 return ⇒ **那個旗從頭到尾沒有作用過**，
           而畫面上什麼錯誤訊息都沒有。
         · 而「整段追擊不斷曲」**-1420 起早就由城上的 `bgmWhen` 負責**
           （`need:'bl_chase1'` → gothic），這一行留著純粹是 -1398 的遺物。
       ⇒ 拿掉它。這一拍到門推上去之前照舊是古城固有的 `numina`（Ray：「遭遇龍之前」）。
       ⚠⚠ 連帶：`bl_chase` 卡上補了 **`bgmAfter:'gothic'`** —— 打完第一場到
         `bl_chase1` 這支旗記下去之間，`resumeFrom` 會把曲子接回**戰前那一首**
         （＝numina），不補的話那兩句對白會snap回古城的曲子。 */
    { flag:'bl_chase1', sides:{ RENNA:'L' }, lines:[
      /* ══⚠⚠ **先降臨，再跑台詞**（ver -1462，Ray：「下一格遭遇龍時先降臨，
         再跑台詞」）══ 牠是**在這一拍出現的** —— 那幾句是對「牠出現了」的反應，
         順序反過來就變成「大家先喊完，牠才來」。
         ⚠ 走**中景層**的降臨（`cgBack` ＋ `cgBackRise`，ver -1414：「戰鬥中不播降臨，
           劇情出場時播」）—— 與祭壇那一段同一套（鐵律 8），不要另寫一個。
         ⚠ `cgBack` 寫**明確路徑**（它不走時段候選鏈），而且要帶 `?v=2`：
           那張圖是同名覆蓋（-1450 美術重切翅膀），不帶版號會吃到舊快取（§5 的 -650）。
         ⚠ **要有人收**：打完那一場的下一拍寫 `cgBack:null`（同祭壇那一段）。 */
      /* ⚠ ver -1465：`shake` → `roarBlast`（Ray -1443：龍吟是**迎面衝擊的模糊**，
         不是震動）。兩者不可以一起寫 —— 都動 transform，後掛的會蓋掉前一個。 */
      { speaker:'NARRATION', text:'', roarBlast:true, auto:900,
        se:'se_monsterroardeep', cgBackScale:0.9, cgBackRise:true, cgBackFit:'contain',
        cgBack:'resources/enemy/mon_dragon_v1_shackled.webp?v=2' },
      sor('guardtalk','喔！學不乖的傢伙！'),
      any('argue','小偷龍！'),
      nou('awkward','叫人家小偷龍實在有點……'),
      ren('run','小心！要來了！'),
      { battle:'bl_chase' },
      /* ⚠ 收掉中景層那隻龍（牠跑了）—— 不收的話牠會一路跟著你逛古堡（同祭壇那一段）。 */
      Object.assign(nou('cringe','啊！又跑了！'), { cgBack:null }),
      sor('readysmile','別以為逃得過獵手的追蹤喔！'),
    ] },
    /* ② */
    { flag:'bl_chase2', sides:{ RENNA:'L' }, lines:[
      { battle:'bl_chase' },
      nou('surprise','往那邊去了！'),
      sor('ready','我怎麼覺得這傢伙在挑釁我！'),
    ] },
    /* ③ */
    { flag:'bl_chase3', sides:{ RENNA:'L' }, lines:[
      { battle:'bl_chase' },
      sor('furiousq','啊——！我受不了了！'),
      sor('furiousq','我要把那隻小偷龍烤來吃！'),
      nou('shocked2','禍魘不能吃啦！'),
      /* ⚠ ver -1421（Ray：「諾薇兒說禍魘不能吃的時候，下一個 hungry 要播肚子餓音效」）
         —— 這一拍**沒有台詞**（只有立繪），聲音就是那句沒說出口的話。 */
      Object.assign(nou('hungry',''), { se:'Se_Tummy' }),
      any('nervous','肚子，餓了？'),
      nou('lookaway','不是那樣啦——今天實在走太多路了！'),
    ] },
    /* ④ 打完這一場就逼進王座廳（紅點從此亮起）。 */
    { flag:'bl_chase4', sides:{ RENNA:'L' }, lines:[
      { battle:'bl_chase' },
      ren('lookup','這樣下去沒完沒了！'),
      ren('thinking','牠在消耗我們體力。'),
      nou('cringe','那怎麼辦？'),
      ren('command','把他往死胡同逼！'),
      /* ══⚠⚠ **「交給我！」以後開小地圖，龍出現在當前格的隔壁任一位置**
         （ver -1421，Ray 交辦）══
         · `map:true` ＝這一拍把小地圖攤開（演出模式，不吃點擊；同安雅指路那一段）
         · `flags:['bl_dragon_seen']` ＝**從這一刻起牠在圖上看得見**
           —— `dragonAtNode()` 就是看這一支旗（在那之前照 Ray 的原話是「瞎找」）
         ⚠⚠ 「擺到隔壁」由 `modules/town.js` 的 `dragonPlaceNear(nodeId)` 做
           （鐵律 7：牠在哪一格只有那一支在答）—— 這裡只負責**讓它看得見**。
         ⚠ 下一句「那氣味我記住了！」**演在地圖上**（Ray 指定）：地圖是持續狀態，
           攤開之後一直在，段落講完才自己收（`clearCast`）。 */
      Object.assign(sor('guard','交給我！'), { map:true, flags:['bl_dragon_seen'] }),
      sor('back','那氣味我記住了！'),
    ] },
  ],
  /* ══⚠⚠ **第五場以後**（ver -1421，Ray：「從開圖開始起算超過 5 場…」）══
     前四場是寫好的稿（各有旗、只演一次）；之後每一次追上牠就用這一段。
     ⚠ **沒有 `flag`** ＝可以重複（`actDue` 只跳過旗立了的段落）。不會無窮迴圈：
       打完牠就跑掉了（`dragonFleeStep`），玩家得再追上才會再觸發。
     ⚠ Ray 沒給這幾場的台詞 —— 只有戰鬥拍，不替他編。 */
  chaseMore: { sides:{ RENNA:'L' }, lines:[ { battle:'bl_chase' } ] },
  /* ══⚠⚠⚠ **開圖三戰之後**（ver -1433，Ray 交稿）══════════════════════════════
     「開圖」＝索菈娜「交給我！」那一拍（`bl_dragon_seen`）；之後**又打了三場**
     就跳這一段 —— 它不必踩到牠，走一步就會演（判定在 `modules/town.js` 的
     `dragonTalkDue`，計數也在那邊，鐵律 7：這裡只有台詞）。
     ⚠ 只演一次（`flag`）。⚠ 沒有戰鬥拍：這是打完之後的一段喘息，不是一場架。 */
  afterThree: { flag:'bl_chase_talk3', sides:{ RENNA:'L' }, lines:[
    nou('cringe','牠一直往我們的反方向跑！'),
    sor('battlecry','這樣反而好預測！'),
    ren('command','把牠逼到最深處就無路可跑了！'),
    any('steady','小偷龍！'),
    nou('awkward','還在講那個……'),
  ] },
  /* ⑤⑥ 王座廳：**第二型態**決戰 → 轉空中 → 索菈娜索敵後出現 → 空中戰
     （Ray：「逼到王座廳以後第二型態決戰　戰勝後轉空中　索拉娜索敵後出現　展開空中戰」）。
     ⚠ 兩場在**同一段**裡：中間那幾拍是同一段演出（上船、索敵），拆成兩個 act
       會多一次「走到某一格」的要求，而船上沒有格子可以走。 */
  /* ⚠ ver -1420：`goto:'entrance'` **拿掉** —— 這一段的出口 -1417 起是 `goFlight`
     （上船追），不是走回中庭。留著的話 `endScene` 的收尾會在交棒前一刻
     再推一次強制轉場。⚠ `flag` 照舊記得到：`goFlight` 是先 `endScene()`（跑收尾、
     記旗）才叫開啟器的。 */
  /* ⚠⚠⚠ **出口走 `sailOut:true`，不是劇情層的 `{goFlight:true}`**（ver -1426，
     Ray：「上船追以後卡住不跑了」）══
     `{goFlight:true}` 是**主線 scene** 那一層的拍：它會先 `endScene()`，而城鎮段落的
     `endScene` 會把 **act 的收尾整條跑完** —— 裡面還有「還有下一段就原地接上」與
     開導覽。於是收尾把畫面要回去、`flightOpener` 又要開飛行頁，**兩邊搶同一個舞台**
     ⇒ 卡住。
     ⚠ `sailOut:true` 是城鎮段落**自己的**出航出口（ver -741 就有）：收尾跑到那裡
       `suspend()` → `flightOpener(sailFrom())` → **`return`**，不會再往下接。
     ⚠ 旗與曲子改掛在「上船追！」那一句上（`applyPersist` 逐拍套用）—— 那正是登船的那一刻。 */
  throne: { flag:'bl_night_throne', sailOut:true, sides:{ RENNA:'L' }, lines:[
    { battle:'bl_throne' },
    { speaker:'NARRATION', text:'', shake:true, auto:800 },
    /* ⚠⚠ ver -1416（Ray：「蕾娜的『小心！要垮了！』的時候畫面持續抖動，
       播放破瓦音直到音檔播完才停」）：`shakeHold:'se'` ＝抖到這一拍的音效播完
       （長度問音檔，不在這裡寫秒數 —— §6.5.5）。
       ⚠ `shakeHold` 是**跨句的狀態**，推對話不會收掉；出口是進戰鬥／換場／離場
         三個，全部走 `stopShake()`（§6.5 的 -638）。 */
    /* ⚠ ver -1433（Ray：「『小心！要垮了！』同時播 `se_rockimpact`」）——
       **一拍兩個聲音**（`se` 吃陣列）：崩瓦是碎、落石是砸，兩個一起才是「垮」。
       ⚠ `shakeHold:'se'` 的長度問的是**第一支**音檔（`se_brickcrush`）。 */
    Object.assign(ren('intense','小心！要垮了！'),
      { se:['se_brickcrush','se_rockimpact'], shakeHold:'se' }),
    sor('furiousq','跑出去了！'),
    nou('shocked2','讓牠襲擊城鎮就不好了！'),
    /* ⚠⚠⚠ ver -1433（Ray：「上船追換 warhorn 是**進到飛行畫面以後**換」）——
       `bgm:'warhorn'` 從這一拍**拿掉**了：這一刻人還站在王座廳裡（-1398 的
       「登船前用 warhorn」被讀成了「說這句話的時候」）。曲子改由
       `config.flightBgmWhen` 在**進飛行畫面那一刻**決定（鐵律 7：只有一個地方在答）。
       ⚠ `bl_sky_hunt` 照舊掛在這裡 —— 那正是「上船」這個事件本身（鐵律 9）。 */
    Object.assign(ren('command','上船追！'), { flags:['bl_sky_hunt'] }),
    /* ══⚠⚠⚠ **這一段到此為止，接下來在飛行頁演**（ver -1416，Ray：「蕾娜『上船追！』
       之後轉景，從古城升空…索『諾薇兒，安靜下』之後，提示長按…發動獵手之眼索敵。
       索敵後必出王座徘徊者…然後進入空戰」）══
       搬到 `flight/index.html` 的有三段（都在那邊，**這裡不要留第二份**）：
         · `SKY_HUNT_TALK`  諾「一片黑」／索「諾薇兒，安靜下！」＋ 索敵的教學閘門
         · 劇本遭遇 `bl_sky_hunt`（`onSense:true` ＝索敵完成才生）→ 戰鬥卡 `bl_sky`
         · `SKY_WIN_TALK`   打贏之後那三句
       ⚠⚠ `bl_night_sky` 由飛行頁的 `settleScriptResult` 依 `done` 記（**打贏才記**）
         —— 原本掛在最後一句上的 `flags` 拿掉了，兩個插旗點就是鐵律 9 的病。
       ⚠ `bgm:'warhorn'` 跟著搬不了（飛行頁有自己的一套音樂），改掛在這一拍：
         「登船進空中戰前用 warhorn」的登船就是**這一刻**。 */
  ] },
};

/* ══⚠⚠⚠ **任務探索：追蕾娜的髮飾**（ver -1416，Ray 交辦）══════════════════════
   > 「那傢伙比你還急之後任務探索　不能約會　不能睡覺　可以出航
   >   但不能降落在古城以外的地方　降其他地方就輪跳」

   **一個旗，一支判定**（鐵律 7/9）：誰插＝那一夜演完（`ep_night_raid` 最後一拍）、
   誰拔＝空中戰打完（`bl_night_sky`）。中間這一段玩家是**自由的**，只是路只有一條。

   ⚠⚠ **這一版把 `ep_night_raid` 的 `goto:'@belisar:greathall'` 拿掉了** ——
     Ray 說「可以出航」，那就表示**要玩家自己飛過去**；還留著強制轉場的話，
     那三條限制一條都碰不到（人已經被搬到古城裡了）。
     連帶：那一拍同時插 `belisar_land_ok` —— 在此之前古城是**降不下去**的
     （`flight/index.html` 的 `belisarLandGate`，-1279 立好的門，一直等著有人插旗）。
   ⚠ **降落限制那一份在飛行頁**（`flight/index.html` 的 `HUNT_*`）：那是另一個
     document，import 不到這裡（§6.10 的跨頁慣例，兩邊註解互指）。台詞也在那邊 ——
     **不要在這裡抄第二份**。
   ⚠ 「不能約會／不能睡覺」的那兩句是**旁白**（名字欄空）＝主角自己的念頭，
     同旅店 `noSleep` 那一句的作法（§6.5.5）。 */
export const QUEST_LOCK = {
  flag:  'ep_hairpin_hunt',
  until: 'bl_night_sky',
  sleep: '（不是睡覺的時候。得快點追上去。）',
  date:  '（現在不是約人出門的時候。）',
};

export const OUTING = {
  /* ⚠ ver -1102 由 [8,18] 改成 [9,19]（Ray 的 Stage9 稿：「夥伴有可能的出門時間
     是 09：00 到 19：00」）—— 上界與 `backHour` 是同一個鐘點（出了門就待到 19:00）。 */
  hours: [9, 19],
  /* ══ 宵禁（ver -576，Ray 定案）══════════════════════════════════════════
     「晚上九點以後女主角就不出門，約不出來。改放天晚休息了之類的台詞，
       到隔天七點以後才恢復。」
     ⚠ 跨午夜，上界不含（同節點的 `hours`）：21:00 ~ 06:59 成立。
     ⚠ 判定只有 `modules/town.js` 的 `isCurfew()` 一支：外出行程與旅店敲門
       都問它（鐵律 8）。敲門那一句在節點的 `innStage1.nightRest`。 */
  curfew: [21, 7],
  /* ══⚠⚠⚠ **送她回旅店：演完告別才解除同行**（ver -1369，Ray：「回旅店女主觸發
     告別對話後同行就會解除」）══════════════════════════════════════════════
     ⚠⚠ **ver -1097 曾經把「走進旅店就解除約會」整條拿掉** —— 當時的理由是
       「帝都還沒有設計約會事件，只會變成無意義的動作」（Ray 原話）。
       **那個理由現在不成立了**（東泊有整組約會戲），而且 Ray 這一次要的與 -576
       那一版**不一樣**：-576 是**默默解除**，這一版是**先演一段告別**再解除 ——
       多了那一段，它才不是「無意義的動作」。⇒ -1097 不是被推翻，是**前提變了**。
     ⚠⚠ 這是**世界規則**（同宵禁），所以機制全域；**台詞是資料**（鐵律 1）：
       城可以寫自己的 `dateBye:{ by:{ WHO:{lines} } }` 覆寫，沒寫就用這一組。
       ⚠ 同 `innStage1.nightRest` 那條的作法（四扇門共用一句、專屬的才另寫）。
     ⚠⚠⚠ **不掛旗**（與 `dateCurfew` 的差別）：那一段是「這一次的約會結束了」，
       **每一次送她回來都要演**。掛了旗第二次就不演 ⇒ `endDate` 也跟著不跑
       ⇒ **同行永遠解除不掉**。
     ⚠⚠⚠ **ver -1383：那一句暫代的旁白拿掉了**（Ray：「回到旅店不用顯示她停下腳步」）。
       ⚠⚠ **機制留著、只是沒有台詞**：`lines` 空陣列 ＝ `actDue` 取到之後直接跑收尾
         （同東泊那一段「安靜抵達」的作法）—— `endDate:true` 照樣會跑，
         **同行照樣解除得掉**。這一格不可以整個拿掉，拿掉就沒有人解除同行了。
       ⚠ 有各自的稿就往**城的** `dateBye.by[WHO].lines` 加，這裡一個字都不必動。 */
  dateBye: { node:'inn', lines:[] },
  /* ══⚠⚠ 約會的好感門檻（ver -1096，Ray：「T3 以上可以約會」→「不過這麼前期，
     還是設成 T2 吧，免得連教學都開不了」）══
     **一個數字一個地方**（鐵律 1/7）：`modules/town.js` 讀它、注入給 `inn.js`，
     敲門那一支只比大小，不自己記門檻。
     ⚠ 值＝**好感點數**不是段位號：段寬 20（`progress.tierOf`），T2 的地板就是 20。
       寫段位號的話這裡就得再算一次 `tierFloor`，那是第二個計算點。 */
  dateAff: 20,
  /* ══⚠⚠ **出了門就不回來，直到 19:00**（ver -1100，Ray：「角色如果出門，
     在 19:00 之前不會回來」）══
     原本是「一天最多兩次、每次待 `stay` 分鐘」（-575）—— 那會讓玩家走到那一格時
     她剛好回房，讀起來是撲空而不是「她今天出門了」。現在一旦排出門，
     結束時刻一律是這個鐘點。
     ⚠ `perDay` 因此實際上只會成真一次（排到第一次就佔滿到 19:00）——
       欄位留著：它仍然決定「一天有幾個機會擲」（時段切幾個窗），
       只是不會再出現「出門→回房→再出門」。 */
  backHour: 19,
  perDay: 2,             // Ray：一天最多出門兩次
  chance: 0.5,           // 每個窗各擲一次（Ray 只說「可能」，數字暫定）
  stay:  [60, 150],      // 一次在外面待多久（分鐘，窗內隨機；暫定）
  /* ⚠ 這張表的**順序就是旅店四扇門的順序**（modules/inn.js 的 `roster()`）——
     諾薇兒在第一格是既有的版面，不要換。 */
  /* ⚠⚠ **指定地點是逐城的**（ver -1100）：節點 id 本來就逐城不同（帝都的
     `cityhall` 在夏爾村根本不存在），而 Ray 的 Stage9 稿給了夏爾村四個專屬地點
     —— 餐廳（諾薇兒）／村長的家（蕾娜）／湖畔（安雅）／獵人小屋（索菈娜）。
     `nodes` 是不分城的預設，`nodesBy[城id]` 覆寫那一座。
     ⚠ 有指定地點的人**就只出現在那裡**（見 `modules/town.js` 的 `areaFor`）——
       不再加上連接場景，不然「她今天在湖畔」會變成「她可能在任何一條路上」。 */
  /* ══⚠⚠ **碰面的那一段戲**（`meetBy[城id]`，ver -1102，Ray 的 Stage9 稿）══
     `line` 是**單句**（路人單句那一套，點一下收掉）；`meetBy` 是**一整段對白**
     （走劇情播放器，立繪／明暗／打字機與別處一致）。
     · 沒寫 `meetBy` 的城照舊走 `line` —— **帝都一個字都不動**
       （Ray：「帝都還沒有設計約會事件，只會變成無意義的動作」）。
     · `lines`      ＝兩種情況都演的那一段。
     · `meet.lines` ＝**偶遇才有**的收尾（Ray：「約會的時候蕾娜是不會有『啊，你也來啦』
                      的，那是偶遇才會有」）—— 約會時整段跳過。
     · `date.lines` ＝**約會派生**：接在 `lines` 後面（不接 `meet`）。
     ⚠⚠⚠ **派生的判準是「現在正在跟她約會」，不是好感**（ver -1102，Ray：
       「通通約會才派生，全部改成T2」）—— 稿上獵人小屋那格寫的「T3 以上或約會」
       已由這句話統一掉：**四個地點一律只有約會才派生**，門檻一律 `dateAff`（T2＝20，
       那是**約不約得出來**的門檻，在旅店敲門那一關就判完了，這裡不再判一次）。
     ⚠ **地點就是 `nodesBy`／`nodes` 那一份**（鐵律 7）：不要在這裡再寫一次節點 id。
     ⚠ 好感走**既有的** `line.aff`（`modules/town.js` 的 `applyAff`，唯一那個記帳點）
       ＝**演完才記**，而且一天一次（見 `metSet`）。
     ⚠ 獵人小屋那一段**沒有好感**：Ray 的稿只給了另外三個地點的數字（+1／+2／+3），
       這一格他沒寫 —— 空著等他補，不要自己填一個。 */
  who: {
    NOUVELLE: { from:1, dine:'restaurant', nodes:['cityhall','church','grocery'],
                nodesBy:{ shinier:['restaurant'] },
                line:'啊，{N}！我正想著要不要買點什麼回去呢。',
                meetBy:{ shinier:{
                  lines:[ nou('concern','這麼棒的料理，我怕以後吃不到……') ],
                  date:{ lines:[ { speaker:'PLAYER', blank:true },
                                 nou('surprise','咦？你也是嗎？'),
                                 nou('bigsmile','那我們一起吃吧！'),
                                 nou('shy','……我可以再點一份嗎？', { aff:{ nouvelle:1 } }) ] } } } },
    RENNA:    { from:1, dine:'cafe',       nodes:['cityhall','church','grocery'],
                nodesBy:{ shinier:['chief'] },
                line:'寫報告寫累了，出來透透氣。',
                /* ⚠ 蕾娜本位左、村長本位右（speakers.js）→ 兩個人自然分兩邊，
                     不必給 `sides` 覆寫（§6.5）。 */
                meetBy:{ shinier:{
                  lines:[ ren('writting','原來如此……遺蹟從未有過那樣的反應？'),
                          chf(null,'這個村子建立也不過幾十年，再往前的事我也不清楚。'),
                          chf(null,'不過魔獸的量明顯減少了，謝謝你們啊。'),
                          ren('smile','不會，這是聖王廳應盡的職責……') ],
                  /* ⚠⚠ 「啊，你也來啦。」是**偶遇**才有的（ver -1102，Ray：「約會的時候
                     蕾娜是不會有『啊，你也來啦』的，那是偶遇才會有」）—— 約會是一起
                     走進來的，她不會對身邊的人說「你也來啦」。 */
                  meet:{ lines:[ { speaker:'PLAYER', blank:true },
                                 ren('ask','啊，你也來啦。') ] },
                  date:{ lines:[ ren('arguecute','也不能怪我們啊！從來沒有收到過求救嘛！'),
                                 chf(null,'還不到需要求救的程度啦，魔獸的爪牙價格很好，源源不絕地自己送上門來也很不錯。'),
                                 ren('shockedCalm','我這輩子沒想到能聽到這種話……', { aff:{ renna:2 } }) ] } } } },
    ANYA:     { from:5, dine:'dessert',    nodes:['grocery'],
                nodesBy:{ shinier:['lakeside'] },
                line:'……嗯。今天的份，還沒吃到。',
                meetBy:{ shinier:{
                  lines:[ any('watch','好漂亮……'),
                          { speaker:'PLAYER', blank:true },
                          any('talk','有，可是都結冰。') ],
                  date:{ lines:[ any('talk','這個地方，我很喜歡……'),
                                 { speaker:'PLAYER', blank:true },
                                 any('shy',''),
                                 any('talkshy','好。', { aff:{ anya:3 } }) ] } } } },
    /* ⚠⚠⚠ **索菈娜 S8 才入隊**（ver -1360，Ray：「s8 之前她不論如何不會在，
       因為還沒入隊」）—— 原本是暫填 5（入隊章節未定時的佔位）。
       `girlsHere()` 依它濾旅店的四扇門 ⇒ S8 之前那一格根本不存在，
       不必再用「好感不夠就當她不在」去近似（見下面夏爾村那一段拔掉的 `absent`）。
       ⚠ `flight/talks.js` 的 `PARTY.sorana` 是**同一件事的另一份**（船上對話），
         兩邊註解互指 —— 改一邊要改另一邊（鐵律 7 的但書）。 */
    SORANA:   { from:8, dine:'bar',        nodes:['grocery','gunstore','guild'],
                nodesBy:{ shinier:['hunter'] },
                line:'喲。難得看你走這條路啊。',
                meetBy:{ shinier:{
                  lines:[ sor('lauaghbig','好，今天的目標是山豬！') ],
                  date:{ lines:[ sor('smirk','要不要來比賽呀？'),
                                 sor('tease','要是你贏的話……就……'),
                                 sor('idea','就算你贏啦！') ] } } } },
  },
};

/* ══════════════════════════════════════════════════════════════════════
   餐飲街的分店（ver -575；-578 把「店長什麼樣」搬到城上）
   ──────────────────────────────────────────────────────────────────────
   「大城地圖已經規則化，餐飲街方向會出什麼場景取決於同行女伴，或者當下是誰在那個
     區域。」「無女伴、且該場景無分配角色時就是酒吧。」

   判定順序（`modules/town.js` 的 `dineKey()`，只有那一支）：
     ① 同行女伴的 `dine`  ② 現在在餐飲街那一格的人的 `dine`  ③ 都沒有 → `fallback`
   ⚠ 分店只換**背景、地名與路人語**，不是另一個節點 —— 出口、營業時間、店主
     都還是那一格的。
   ⚠⚠ **「哪一家店」是全域概念，「那一家店長什麼樣」是這座城的事**（ver -578）：
     這裡只留店別的中文名；**背景檔名、要不要吃時段差分、路人語**寫在城的
     `dining.scenes[店別]` 上 —— 每座城的餐飲街是不同的四家店，
     用一個共同的檔名後綴去拼一定會走鐘（-575 曾經是 `<節點bg>_cafe`，
     而 Ray 交件的檔名是 `Capital_Cafe`，根本不同源）。
       dining:{ node:'tavern', scenes:{
         cafe:{ bg:'Capital_Cafe', noTime:true, chatter:[…] }, …
       }}
     · `bg` ＝**完整基底名**（不是後綴）。
     · `noTime:true` ＝這張圖沒有時段差分，候選鏈只試原名 —— 不寫的話會先吃
       `_Day`／`_Dusk`／`_night` 一輪 404（§6.5.4 的候選鏈）。
     · 城裡沒有那一家（`scenes` 沒這個鍵）→ **不換**，照節點原本那一張。
   ⚠ 只寫 `{ node:'tavern' }`（不給 `scenes`）＝那一格只是「可以碰到人的地方」，
     不換分店 —— 北方泊地的四張圖還沒交，現在就是這樣。
   ══════════════════════════════════════════════════════════════════════ */
export const DINE = {
  fallback: 'bar',       // Ray：無女伴、該場景無分配角色 → 酒吧
  /* ⚠ `name` **不會出現在畫面上**（ver -580，Ray：地名一律是「餐飲街」）——
     它是除錯與文件用的（`town.outingDebug()` 印得出來）。玩家看得出自己在哪一家
     靠的是背景與路人語，那正是「點進去會進哪邊」這件事本身。 */
  scenes: {
    cafe:       { name:'咖啡廳' },
    restaurant: { name:'餐廳'   },
    dessert:    { name:'甜品店' },
    bar:        { name:'酒吧'   },
  },
};

/* ══⚠⚠⚠ 貝利薩爾：**第一次走到有水的地方**（ver -1409，Ray 交稿）══════════════
   Ray：「第一次走到有水的地方時會跳索拉娜『哇！這地方怎麼到處都是水』…」

   ⚠⚠ **一個段落物件，六格共用**（鐵律 7：一份真相）。「第一次」是**旗標**保證的
     —— `actDue` 跳過旗立起來的段落，所以**先踩到哪一格就在哪一格演**，之後五格
     全部安靜。逐格各抄一份的話，改台詞要改六次，而且必然有一次漏掉。
   ⚠ 也因此**不可以給它 `until`**：那是「別人那一段演完就不再演」，這一段要的是
     「自己演過就收工」＝`flag`（§6.5.4 的 -668）。

   ⚠⚠ **哪幾格「有水」照規格書逐格的描述，不照名字猜**
     （`resources/map/_undercity_spec.md`；憲法 -890：地圖的形狀是圖決定的）：

     | 格 | 規格書怎麼寫 |
     |---|---|
     | 千柱廳 `pillars`    | 柱子**泡在淺水裡** |
     | 獅口水道 `dragonrace` | 水從獅頭石雕口流出、**沿廊而下** |
     | 水牢 `waterjail`    | 地面全是**及膝**的水 |
     | 暗渠 `culvert`      | 水到**腳踝** |
     | 積水甬道 `floodway` | **積水到膝**，壁上一條清楚的水痕線 |
     | 靜水池 `mirrorpool` | 一池不流動的黑水 |

     ⛔ **枯井底 `drywell` 是乾的**（名字就寫著）、**排水崖口 `draincliff` 是排水道
       開在崖壁上的出口**（「腳下沒有路」，戶外）—— 兩格都不算，別被「井」「排水」
       這兩個字帶著走。

   ⚠ **不必寫 `skipIf:'ep_bel_altar'`**（三段提示要寫是因為它們沒有終點）：
     祭壇**只能從積水甬道進**（施工單的驗收條件），而積水甬道就在這張表上 ——
     所以這一段必定在龍出現之前就演完了。
   ⚠ `need:'ep_bel_enter'` ＝走進古城那一段演完才算，同三段提示的起算點。
   ⚠ `sides:{ RENNA:'L' }` ＝四個人同台：索菈娜與安雅本位右、諾薇兒本位左，
     蕾娜碰到安雅就放左（§6.5 那張表）。 */
const BEL_WATER_FIRST = {
  flag:'bel_water', need:'ep_bel_enter', sides:{ RENNA:'L' }, lines:[
    sor('cringe','哇！這地方怎麼到處都是水。'),
    ren('ask','不只是那樣……'),
    ren('talkwork','文獻裡的古城不是這樣子的。'),
    nou('surprise','不是這樣子的？'),
    /* ⚠ Ray 的稿寫「think」，`speakers.js` 那張差分叫 **`thinking`**。 */
    ren('thinking','這是大陸曆之前的建築了，但現在看起來卻像是剛剛才被破壞一樣……'),
    any('silent','……'),
  ] };

